cd /root/bench-runs/h4-c3e12a23/test && cat > app-startup-list.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { loadApp, flush, childSummary, booking, loadReadyApp } from './helpers/fake-dom.mjs';

const ROOMS = ['Aurora', 'Borealis', 'Cosmos'];

function assertOnlyAllowedApis(page) {
  assert.deepEqual(page.forbidden, []);
}
function isGet(call) {
  return call.options === undefined || call.options.method === 'GET';
}
function callFor(page, url) {
  return page.calls.find((c) => c.url === url);
}
function lis(page) {
  return page.elements['booking-list'].childNodes;
}
function summaries(page) {
  return lis(page).map((li) => childSummary(li));
}
function errorText(page) {
  return page.elements.error.textContent;
}
async function changeFilter(page, value) {
  page.elements['filter-date'].value = value;
  const before = page.calls.length;
  page.elements['filter-date'].dispatch('change');
  await flush();
  assert.equal(page.calls.length, before + 1);
  return page.calls[before];
}
async function roomsReply(reply) {
  const page = loadApp();
  await flush();
  reply(callFor(page, '/api/rooms'));
  await flush();
  return page;
}
const row = (text) => [{ text }, { tag: 'button', type: 'button', text: 'Cancel' }];

test('startup issues both GET fetches synchronously without waiting for rooms', () => {
  const page = loadApp();
  assert.equal(page.calls.length, 2);
  assert.deepEqual(page.calls.map((c) => c.url).sort(), ['/api/bookings', '/api/rooms']);
  for (const call of page.calls) {
    assert.ok(isGet(call));
    assert.equal(call.options?.body, undefined);
  }
  assertOnlyAllowedApis(page);
});

test('rooms success fills #room with one option per room in order, value equals name', async () => {
  const page = await roomsReply((c) => c.respond(200, { rooms: ROOMS }));
  assert.deepEqual(childSummary(page.elements.room), ROOMS.map((text) => ({ tag: 'option', type: undefined, text })));
  assert.deepEqual(page.elements.room.childNodes.map((o) => o.value), ROOMS);
  assertOnlyAllowedApis(page);
});

for (const [status, body, expected] of [
  [500, { error: 'boom' }, 'boom'],
  [404, { error: 5 }, 'Request failed.'],
  [500, ['x'], 'Request failed.'],
  [500, null, 'Request failed.'],
]) {
  test(`rooms error status ${status} with body ${JSON.stringify(body)} shows "${expected}" and leaves #room empty`, async () => {
    const page = await roomsReply((c) => c.respond(status, body));
    assert.equal(errorText(page), expected);
    assert.deepEqual(page.elements.room.childNodes, []);
    assertOnlyAllowedApis(page);
  });
}

for (const [name, act] of [
  ['fetch fails', (c) => c.fail()],
  ['500 unparseable', (c) => c.respondUnparseable(500)],
  ['200 unparseable', (c) => c.respondUnparseable(200)],
]) {
  test(`rooms with no usable reply (${name}) shows unreachable message and leaves #room empty`, async () => {
    const page = await roomsReply(act);
    assert.equal(errorText(page), 'Could not reach the server.');
    assert.deepEqual(page.elements.room.childNodes, []);
    assertOnlyAllowedApis(page);
  });
}

test('list renders each booking as li with one text node and a Cancel button, in reply order', async () => {
  const a = booking({ id: 2, room: 'Borealis', title: 'Later', date: '2026-11-05', start: '13:00', end: '14:30' });
  const b = booking({ id: 1 });
  const page = await loadReadyApp([a, b]);
  assert.equal(lis(page).length, 2);
  assert.deepEqual(summaries(page), [
    row('2026-11-05 13:00-14:30 Borealis: Later'),
    row('2026-11-03 09:00-10:00 Aurora: Standup'),
  ]);
  assert.equal(lis(page)[0].childNodes[0].constructor.name, 'TextNode');
  assertOnlyAllowedApis(page);
});

test('list shows a title with markup literally as text', async () => {
  const page = await loadReadyApp([booking({ title: '<b>x</b>' })]);
  assert.deepEqual(summaries(page), [row('2026-11-03 09:00-10:00 Aurora: <b>x</b>')]);
  assertOnlyAllowedApis(page);
});

test('list text has no trailing or extra whitespace beyond the title', async () => {
  const page = await loadReadyApp([booking({ title: 'Plan  ' })]);
  assert.equal(lis(page)[0].childNodes[0].data, '2026-11-03 09:00-10:00 Aurora: Plan  ');
  assertOnlyAllowedApis(page);
});

test('empty list shows exactly one li containing only the text node "No bookings."', async () => {
  const page = await loadReadyApp([]);
  assert.equal(lis(page).length, 1);
  assert.deepEqual(childSummary(lis(page)[0]), [{ text: 'No bookings.' }]);
  assertOnlyAllowedApis(page);
});

test('a refetch replaces the rendered list instead of appending', async () => {
  const page = await loadReadyApp([booking({ id: 1 }), booking({ id: 2 }), booking({ id: 3 })]);
  assert.equal(lis(page).length, 3);
  const call = await changeFilter(page, '2026-11-03');
  call.respond(200, { bookings: [booking({ id: 4, title: 'Only' })] });
  await flush();
  assert.equal(lis(page).length, 1);
  assert.deepEqual(summaries(page), [row('2026-11-03 09:00-10:00 Aurora: Only')]);
  assertOnlyAllowedApis(page);
});

for (const [name, act, expected] of [
  ['error status', (c) => c.respond(400, { error: 'date must be a valid YYYY-MM-DD date' }), 'date must be a valid YYYY-MM-DD date'],
  ['no reply', (c) => c.fail(), 'Could not reach the server.'],
  ['unparseable', (c) => c.respondUnparseable(200), 'Could not reach the server.'],
]) {
  test(`list fetch failure (${name}) shows the error and leaves the list unchanged`, async () => {
    const page = await loadReadyApp([booking()]);
    const before = [...lis(page)];
    const beforeSummary = summaries(page);
    const call = await changeFilter(page, 'bad');
    act(call);
    await flush();
    assert.equal(errorText(page), expected);
    assert.equal(lis(page).length, before.length);
    assert.ok(lis(page).every((li, i) => li === before[i]));
    assert.deepEqual(summaries(page), beforeSummary);
    assertOnlyAllowedApis(page);
  });
}

test('list success leaves an existing #error message alone', async () => {
  const page = loadApp();
  await flush();
  callFor(page, '/api/rooms').respond(500, { error: 'boom' });
  callFor(page, '/api/bookings').respond(200, { bookings: [booking()] });
  await flush();
  assert.equal(errorText(page), 'boom');
  assert.equal(lis(page).length, 1);
  assertOnlyAllowedApis(page);
});

test('stale list fetch (a): older success arriving after newer success is ignored', async () => {
  const page = loadApp();
  const a = callFor(page, '/api/bookings');
  const b = await changeFilter(page, '2026-11-03');
  b.respond(200, { bookings: [booking({ title: 'b1' })] });
  await flush();
  a.respond(200, { bookings: [booking({ title: 'a1' })] });
  await flush();
